INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Frankly Speaking: Live with Dr. Frankie Bashan', 'Boston & Worldwide Lesbian, Bi, Trans & Queer+ Events', 'General Networking', 'Bring your questions and join Dr. Frankie for honest conversations about dating, relationships, intimacy, communication, and more. **What', 'Bring your questions and join Dr. Frankie for honest conversations about dating, relationships, intimacy, communication, and more. **What Have You Always Wanted to Ask?** What if you had a space where no dating or relationship question felt too small, too complicated, or too awkward to ask? **Frankly Speaking** is a 60-minute virtual conversation with Dr. Frankie Bashan, licensed clinical psychologist, certified sex therapist, and founder of Little Gay Book. Each session explores the real More info: https://www.meetup.com/boston-lesbian-mixers-events-activities/events/315963078/', '2026-10-26T20:30:00-04:00', 'Online event', 'Online event', 'Boston', 'MA', '', 42.36, -71.07, 'Boston & Worldwide Lesbian, Bi, Trans & Queer+ Events', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/boston-lesbian-mixers-events-activities/events/315963078/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Navigating the Downshift: An Agent, a Lender, and a Builder on What’s Next', 'Boston Real Estate Connection', 'Real Estate', 'When the real estate market slows, how do you adjust—and where do you look for opportunity? Join **Boston Real Estate Connection on October', 'When the real estate market slows, how do you adjust—and where do you look for opportunity? Join **Boston Real Estate Connection on October 28th** for a conversation exploring the market from three perspectives: an agent, a lender, and a builder. We’ll discuss what they’re seeing, how they’re adapting, and what it means for your next deal. Topics will include: * **Buying and selling:** Pricing strategies, buyer expectations, and what helps a property move. * **Financing:** How lending More info: https://www.meetup.com/boston-real-estate-connection/events/316818215/', '2026-10-28T18:30:00-04:00', 'Residence Inn by Marriott Boston Natick', '1 Superior Dr, Natick, MA 01760, USA', 'Natick', 'MA', '01760', 42.300890904318, -71.379867245527, 'Boston Real Estate Connection', 11, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/boston-real-estate-connection/events/316818215/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Fix and Flip Series : Time Hacks', 'Boston Real Estate Investor Club', 'Real Estate', 'MONDAY 5 PM PST 7 PM CST 8 PM EST [SIGN UP HERE](https://link.elitereimm.com/widget/form/wSbrsstjtpMx77vSSif7?am_id=debbie5574) Use CRM,', 'MONDAY 5 PM PST 7 PM CST 8 PM EST [SIGN UP HERE](https://link.elitereimm.com/widget/form/wSbrsstjtpMx77vSSif7?am_id=debbie5574) Use CRM, systems, automation, and AI to run flips more efficiently without letting every project take over your life. Fixing and flipping can become a full-time job fast. Contractors need answers. Materials need to be ordered. Draws need to be tracked. Budgets change. Inspections get scheduled. Properties need to be marketed. And somehow you are still supposed to find More info: https://www.meetup.com/boston-real-estate-investor-club/events/316780046/', '2026-10-12T20:00:00-04:00', 'Online event', 'Online event', 'Boston', 'MA', '', 42.36, -71.07, 'Boston Real Estate Investor Club', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/boston-real-estate-investor-club/events/316780046/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('[Virtual] Simple Real Estate Strategies That Work (Fun, Free, & Gets You Paid!)', 'Boston Real Estate Investor Club', 'Real Estate', '**Most real estate trainings are like bad lectures:** boring, overloaded with information, and leaving you feeling like you’ll need weeks', '**Most real estate trainings are like bad lectures:** boring, overloaded with information, and leaving you feeling like you’ll need weeks of prep just to get started (or worst of all, they just want to sell you their expensive course or coaching). **We decided to do the exact opposite**—and hundreds of agents now agree. Join us **LIVE (virtual) every Wednesday at 9:00 AM CST** for a zero-fluff, action-packed call where active, top-producing agents openly share exactly what’s working right More info: https://www.meetup.com/boston-real-estate-investor-club/events/316694301/', '2026-10-14T10:00:00-04:00', 'Online event', 'Online event', 'Boston', 'MA', '', 42.36, -71.07, 'Boston Real Estate Investor Club', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/boston-real-estate-investor-club/events/316694301/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('RE-AI Advantage Lab: Turn AI Into Your Real Estate Advantage', 'Boston Real Estate Investor Club', 'Real Estate', 'AI is changing what “work” looks like for real estate agents. Tasks that used to take hours can now take minutes. Marketing can be created', 'AI is changing what “work” looks like for real estate agents. Tasks that used to take hours can now take minutes. Marketing can be created faster. Follow up can be smarter. Content can be generated almost instantly. But most agents are still trying to figure out **how to actually use AI in their day-to-day business.** That is exactly what we will be exploring inside the **RE-AI Advantage Lab.** This weekly training is designed specifically for real estate agents who want to learn how to use AI More info: https://www.meetup.com/boston-real-estate-investor-club/events/316694927/', '2026-10-14T11:00:00-04:00', 'Online event', 'Online event', 'Boston', 'MA', '', 42.36, -71.07, 'Boston Real Estate Investor Club', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/boston-real-estate-investor-club/events/316694927/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
