INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('U.S. Visas & Immigration 101 for Startup Founders', 'Boston Startup Founder 101', 'Founders & Startups', 'Building a company in the U.S. is hard enough. Doing it as a non-citizen founder means navigating an immigration system that was never', 'Building a company in the U.S. is hard enough. Doing it as a non-citizen founder means navigating an immigration system that was never designed with startups in mind. This 101 session breaks down the essentials in plain English. You''ll get a clear map of the visa paths open to founders, how they differ, and what each one actually asks of you when you''re the one building the company. We''ll also look at how milestones like fundraising and revenue shape your options, and the mistakes that quietly More info: https://www.meetup.com/boston-startup-founder-101/events/316753087/', '2026-10-12T12:00:00-04:00', 'Online event', 'Online event', 'Boston', 'MA', '', 42.37, -71.07, 'Boston Startup Founder 101', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/boston-startup-founder-101/events/316753087/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('From Dreamer to Doer: Build the Founder Mindset', 'Boston Startup Founder 101', 'Founders & Startups', 'Have you ever wondered why some people take the leap while others stay stuck? The difference isn''t luck, resources, or timing — it''s the', 'Have you ever wondered why some people take the leap while others stay stuck? The difference isn''t luck, resources, or timing — it''s the way founders think. Join Jonathan Greechan, Co-Founder & CEO of the Founder Institute, for a fascinating deep-dive into the psychology behind entrepreneurial action. In this live session, you''ll unpack the cognitive patterns that hold aspiring founders back and explore the mental frameworks that top entrepreneurs use to push through uncertainty. With practical More info: https://www.meetup.com/boston-startup-founder-101/events/316598577/', '2026-10-13T12:00:00-04:00', 'Online event', 'Online event', 'Boston', 'MA', '', 42.37, -71.07, 'Boston Startup Founder 101', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/boston-startup-founder-101/events/316598577/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('How to Raise Money for Your AI Startup as a Solo Founder', 'Boston Startup Founder 101', 'Founders & Startups', 'Solo founders now start a large share of new companies, but they still raise a much smaller share of venture money. Many investors learned', 'Solo founders now start a large share of new companies, but they still raise a much smaller share of venture money. Many investors learned to ask about the co-founder first. **In this session, you will hear how investors assess a solo AI founder in 2026, what makes up for a missing co-founder, and what traction they expect before the first check. Bring your questions for the live Q&A. [RSVP now!](https://fi.co/e/406098/meetup)** **❯ Guest Speakers include:** * Connor Sattely (CEO, Founder More info: https://www.meetup.com/boston-startup-founder-101/events/316851869/', '2026-10-15T12:00:00-04:00', 'Online event', 'Online event', 'Boston', 'MA', '', 42.37, -71.07, 'Boston Startup Founder 101', 7, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/boston-startup-founder-101/events/316851869/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('How to Use AI to Position Your Startup to Buyers', 'Boston Startup Founder 101', 'Founders & Startups', 'You built the product. The market isn''t buying it yet. Usually the gap is positioning: buyers don''t see themselves in your pitch. **In this', 'You built the product. The market isn''t buying it yet. Usually the gap is positioning: buyers don''t see themselves in your pitch. **In this hands-on session, Jonathan Grover shows you how to use AI to fix that. You''ll build a synthetic version of your ideal buyer as an AI agent, then let it tear into your pitch in real time, surfacing the objections and gaps a real buyer would raise.** You''ll leave with sharper positioning that actually converts, plus a Claude skill you can take home and reuse More info: https://www.meetup.com/boston-startup-founder-101/events/316871856/', '2026-10-20T12:00:00-04:00', 'Online event', 'Online event', 'Boston', 'MA', '', 42.37, -71.07, 'Boston Startup Founder 101', 3, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/boston-startup-founder-101/events/316871856/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
