INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Smart Networking - Online Networking and Strategy Sharing', 'Online Business Networking Dallas', 'Real Estate', 'Stop guessing! At the SMART Networking Club, we believe that networking is a learnable skill, and our community is committed to setting you', 'Stop guessing! At the SMART Networking Club, we believe that networking is a learnable skill, and our community is committed to setting you up for success. We don''t just say "be a relationship builder"—we provide the proven, step-by-step process that makes this whole thing netWORK. This is the only club dedicated to the principles of our book, [SMART Networking: The $150,000 Method.](https://cibnconnect.com/betternetworking) Key Highlights: Interactive Networking: Attendees participated in More info: https://www.meetup.com/businessnetworkingdallas/events/316714634/', '2026-10-15T15:00:00-05:00', 'Online event', 'Online event', 'Dallas', 'TX', '', 32.79, -96.8, 'Online Business Networking Dallas', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/businessnetworkingdallas/events/316714634/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
