INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Weekly Job Support and Accountability Group', 'Career Confidence - New York City', 'Founders & Startups', 'Each week we have a 12 minute presentation on the essentials of the job search. You will be able to compare yourself to those essentials to', 'Each week we have a 12 minute presentation on the essentials of the job search. You will be able to compare yourself to those essentials to see if you are on track for a quality job. Too many job seekers spin their time on activity that does not lead to job search success. https://www.youtube.com/watch?v=R20iMmWWsas We want to help you stay focused. More info: https://www.meetup.com/career-confidence-new-york-city/events/316711407/', '2026-10-12T11:00:00-04:00', 'Online event', 'Online event', 'New York', 'NY', '', 40.76, -73.99, 'Career Confidence - New York City', 0, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/career-confidence-new-york-city/events/316711407/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Setting Up LinkedIn So That Recruiters Can Find You', 'Career Confidence - New York City', 'Founders & Startups', 'We will explain the basics of LinkedIn from setting up your profile to how recruiters use LinkedIn to find candidates. 94% of recruiters', 'We will explain the basics of LinkedIn from setting up your profile to how recruiters use LinkedIn to find candidates. 94% of recruiters are highly active on LinkedIn. Therefore, you must be active on LinkedIn so that recruiters can find you. Jerry Jones, a LinkedIn guru, will walk you through the basics of setting up your profile. 1. How Recruiters Find You 2. Simple Strategies for You to Follow 3. Tying Your LinkedIn Profile to Your Job Interview 4. We have had job seekers land quality jobs More info: https://www.meetup.com/career-confidence-new-york-city/events/316854957/', '2026-10-12T13:00:00-04:00', 'Online event', 'Online event', 'New York', 'NY', '', 40.76, -73.99, 'Career Confidence - New York City', 0, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/career-confidence-new-york-city/events/316854957/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Writing Resumes EASY for Recruiters to READ', 'Career Confidence - New York City', 'Founders & Startups', 'Details Coming At the end of this seminar/webinar, there will be a brief Christian story. \-\-\-\-\-\-\-\-\-\-\-\-\-\-\-\-\-\-\- IF YOU ARE', 'Details Coming At the end of this seminar/webinar, there will be a brief Christian story. \-\-\-\-\-\-\-\-\-\-\-\-\-\-\-\-\-\-\- IF YOU ARE NEW TO Career-Confidence.org and want to learn about us via our team, here are some videos that we have done. PLEASE SUBSCRIBE to our channel and LIKE our videos. \-\-\-\-\-\- Career-Confidence.org, Laura Hamilton and Robert Brandau both long-time recruiters give you an overview. More info: https://www.meetup.com/career-confidence-new-york-city/events/316856360/', '2026-10-12T15:00:00-04:00', 'Online event', 'Online event', 'New York', 'NY', '', 40.76, -73.99, 'Career Confidence - New York City', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/career-confidence-new-york-city/events/316856360/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
