INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('[Virtual] Simple Real Estate Strategies That Work (Fun, Free, & Gets You Paid!)', 'Charlotte Real Estate Investing & Marketing Entrepreneurs', 'Real Estate', '**Most real estate trainings are like bad lectures:** boring, overloaded with information, and leaving you feeling like you’ll need weeks', '**Most real estate trainings are like bad lectures:** boring, overloaded with information, and leaving you feeling like you’ll need weeks of prep just to get started (or worst of all, they just want to sell you their expensive course or coaching). **We decided to do the exact opposite**—and hundreds of agents now agree. Join us **LIVE (virtual) every Wednesday at 9:00 AM CST** for a zero-fluff, action-packed call where active, top-producing agents openly share exactly what’s working right More info: https://www.meetup.com/charlotte-real-estate-investing-marketing-entrepreneurs/events/316694097/', '2026-10-14T10:00:00-04:00', 'Online event', 'Online event', 'Charlotte', 'NC', '', 35.15, -80.93, 'Charlotte Real Estate Investing & Marketing Entrepreneurs', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/charlotte-real-estate-investing-marketing-entrepreneurs/events/316694097/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('RE-AI Advantage Lab: Turn AI Into Your Real Estate Advantage', 'Charlotte Real Estate Investing & Marketing Entrepreneurs', 'Real Estate', 'AI is changing what “work” looks like for real estate agents. Tasks that used to take hours can now take minutes. Marketing can be created', 'AI is changing what “work” looks like for real estate agents. Tasks that used to take hours can now take minutes. Marketing can be created faster. Follow up can be smarter. Content can be generated almost instantly. But most agents are still trying to figure out **how to actually use AI in their day-to-day business.** That is exactly what we will be exploring inside the **RE-AI Advantage Lab.** This weekly training is designed specifically for real estate agents who want to learn how to use AI More info: https://www.meetup.com/charlotte-real-estate-investing-marketing-entrepreneurs/events/316694909/', '2026-10-14T11:00:00-04:00', 'Online event', 'Online event', 'Charlotte', 'NC', '', 35.15, -80.93, 'Charlotte Real Estate Investing & Marketing Entrepreneurs', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/charlotte-real-estate-investing-marketing-entrepreneurs/events/316694909/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
