INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('RE-AI Advantage Lab: Turn AI Into Your Real Estate Advantage', 'Charlotte Real Estate Investment Education Network', 'Real Estate', 'AI is changing what “work” looks like for real estate agents. Tasks that used to take hours can now take minutes. Marketing can be created', 'AI is changing what “work” looks like for real estate agents. Tasks that used to take hours can now take minutes. Marketing can be created faster. Follow up can be smarter. Content can be generated almost instantly. But most agents are still trying to figure out **how to actually use AI in their day-to-day business.** That is exactly what we will be exploring inside the **RE-AI Advantage Lab.** This weekly training is designed specifically for real estate agents who want to learn how to use AI More info: https://www.meetup.com/charlotte-real-estate-investment-education-network/events/316694914/', '2026-10-14T11:00:00-04:00', 'Online event', 'Online event', 'Charlotte', 'NC', '', 35.19, -80.83, 'Charlotte Real Estate Investment Education Network', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/charlotte-real-estate-investment-education-network/events/316694914/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('The Unforgettable Realtor Experience', 'Charlotte Real Estate Investment Education Network', 'Real Estate', '**The Unforgettable Realtor Experience** **How to Stay Top of Mind Long After the Closing Table** Most Realtors work incredibly hard to', '**The Unforgettable Realtor Experience** **How to Stay Top of Mind Long After the Closing Table** Most Realtors work incredibly hard to earn the client... and then accidentally disappear after closing. The challenge isn''t that your clients don''t like you. In fact, many of them absolutely love you. The challenge is that life gets busy. If you''re not staying visible in meaningful and memorable ways, someone else eventually becomes the agent they think of when a friend, coworker, neighbor, or More info: https://www.meetup.com/charlotte-real-estate-investment-education-network/events/316711356/', '2026-10-15T12:00:00-04:00', 'Online event', 'Online event', 'Charlotte', 'NC', '', 35.19, -80.83, 'Charlotte Real Estate Investment Education Network', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/charlotte-real-estate-investment-education-network/events/316711356/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
